-- Migration22: explicit versioned battle counters; never infer historical results.
-- Run during maintenance. All older character fields and receipts remain intact.
ALTER TABLE Characters
  ADD COLUMN BattleRecords VARBINARY(176) NOT NULL DEFAULT ,
  ADD CONSTRAINT CK_Characters_BattleRecords CHECK (OCTET_LENGTH(BattleRecords) = 176 AND SUBSTRING(BattleRecords, 1, 4) = 0x01000000);
